#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<char> hi = {'h', 'e', 'l', 'l', 'o'};
    std::string s;
    int counter = 0;
    int length = hi.size();

    if (!(std::cin >> s)) {
        return 1;
    }

    for (char c : s) {
        if (c == hi[counter]) {
            counter++;
            if (counter == length) {
                std::cout << "YES" << std::endl;
                return 0;
            }
        }
    }
    std::cout << "NO" << std::endl;
    return 0;
}

