	hi = []string{"h", "e", "l", "l", "o"}
)

func main() {
	var (
		s       string
		counter int
		length  = len(hi)
	)
	if _, err := fmt.Scanf("%s\n", &s); err != nil {
		log.Fatal(err)
	}

	for i := range s {
		if s[i:i+1] == hi[counter] {
			counter++
			if counter == length {
				fmt.Println("YES")
				return
			}
		}
	}
	fmt.Println("NO")
}
